export const auditRows=rows.map(([id,text,reason])=>({id,text,reason,requiresReview:semanticChanges.includes(id)}));
const byId=new Map(auditRows.map(r=>[r.id,r]));
const domainEdits={2:{name:'속마음을 나누는 정도',low:'개인적인 이야기를 적게 나눔',high:'개인적인 이야기를 많이 나눔'},3:{name:'현재 관계의 지속 지향'},5:{name:'애정 확인의 필요',low:'확인할 필요를 적게 느낌',high:'마음의 확인을 자주 필요로 함'},6:{name:'모임에서의 교류',low:'모임에서 대화 참여가 적음',high:'모임에서 적극적으로 대화'},9:{name:'갈등 대화를 시작하는 시점'},10:{name:'생활 방식을 확인하는 시점',low:'만나면서 차차 확인',high:'관계 시작 전에 확인'},11:{name:'실질적인 도움 행동',low:'실질적인 도움 행동이 적음',high:'실질적인 도움을 자주 제공'}};
const domains=base.domains.map((d,i)=>({...d,...domainEdits[i]}));
const options={62:['표현이 적은 편','적당한 빈도로 표현하는 편','자주 표현하는 편'],63:['개인적인 이야기를 적게 나누는 편','개인적인 이야기를 적당히 나누는 편','감정과 고민을 구체적으로 많이 나누는 편'],67:['모임에서 대화에 적게 참여하는 편','모임에서 적당히 대화에 참여하는 편','모임에서 적극적으로 대화에 참여하는 편'],70:['대화할 수 있어도 충분히 시간을 둔 뒤','상황에 따라 대화 시점을 정하는 편','대화할 수 있으면 가능한 한 빨리'],71:['관계가 시작된 뒤 차차 알아보는 편','알아가는 과정에서 필요할 때 확인하는 편','관계를 시작하기 전에 미리 확인하는 편'],72:['실질적인 도움 행동이 적어도 괜찮음','필요할 때 적당히 실질적으로 돕는 편','도움이 필요할 때 자주 실질적으로 돕는 편']};
export function reviseQuestion(q){const row=byId.get(q.id);if(!row)return q;const d=Math.floor((q.id-1)/4);return {...q,text:row.text,...(options[q.id]?{options:options[q.id]}:{}),...(q.id===48?{reverse:false}:{}),...(q.id<=48?{help:d===3?current:d===9?conflict:d===11?support:habit}:q.id===52?{help:'실제로 즐기는 활동을 최대 5개 골라주세요. 특별히 정한 활동이 없다면 미측정으로 남겨요.'}:q.id===72?{help:'이 문항은 실질적인 도움 행동만 묻고, 상대의 경청이나 공감 능력은 판단하지 않아요.'}:{})};}
export default {...base,domains,questions:base.questions.map(reviseQuestion)};
